;

const ORGAN_LABELS = {
  liver: "Liver",
  spleen: "Spleen",
  kidney_right: "Kidney R",
  kidney_left: "Kidney L",
  aorta: "Aorta",
  inferior_vena_cava: "IVC",
  vertebrae_L1: "L1",
  vertebrae_L2: "L2",
  vertebrae_L3: "L3",
  pancreas: "Pancreas",
  gallbladder: "G.bladder",
};
const ORGAN_COLS = [...DATA.organs, "__OVERALL__"];

const GROUP_ORDER = ["Ablation (aligned)", "Ablation (no-align)", "R-series", "Baselines"];
const GROUP_STYLE = {
  "Ablation (aligned)":   { border: "border-l-sky-500",     dot: "bg-sky-500",    head: "bg-sky-50" },
  "Ablation (no-align)":  { border: "border-l-teal-500",    dot: "bg-teal-500",   head: "bg-teal-50" },
  "R-series":              { border: "border-l-amber-500",   dot: "bg-amber-500",  head: "bg-amber-50" },
  "Baselines":             { border: "border-l-violet-500",  dot: "bg-violet-500", head: "bg-violet-50" },
};

const METRICS = {
  dice:     { label: "Eroded Dice",  unit: "",   domainMax: 1,  goodHigh: true,  fmt: (v) => v.toFixed(2) },
  centroid: { label: "Centroid mm",  unit: "mm", domainMax: 8,  goodHigh: false, fmt: (v) => v.toFixed(1) },
  hd95:     { label: "HD95 mm",      unit: "mm", domainMax: 10, goodHigh: false, fmt: (v) => v.toFixed(1) },
};

// ColorBrewer RdYlGn (7-class), worst -> best
const SCALE = [
  [165, 0, 38],
  [215, 48, 39],
  [244, 109, 67],
  [254, 224, 139],
  [166, 217, 106],
  [26, 152, 80],
  [0, 104, 55],
];

function lerp(a, b, t) { return a + (b - a) * t; }
function colorAt(t) {
  t = Math.max(0, Math.min(1, t));
  const n = SCALE.length - 1;
  const seg = t * n;
  const i = Math.min(n - 1, Math.floor(seg));
  const frac = seg - i;
  const c0 = SCALE[i], c1 = SCALE[i + 1];
  return [lerp(c0[0], c1[0], frac), lerp(c0[1], c1[1], frac), lerp(c0[2], c1[2], frac)];
}
function cellStyle(value, metricKey) {
  if (value === null || value === undefined) {
    return { backgroundColor: "#F1F2F4", color: "#B4B8C0" };
  }
  const m = METRICS[metricKey];
  let t = Math.max(0, Math.min(1, value / m.domainMax));
  if (!m.goodHigh) t = 1 - t;
  const [r, g, b] = colorAt(t);
  const luminance = 0.299 * r + 0.587 * g + 0.114 * b;
  return {
    backgroundColor: `rgb(${r.toFixed(0)},${g.toFixed(0)},${b.toFixed(0)})`,
    color: luminance < 130 ? "#F8FAFC" : "#111827",
  };
}

function organValue(row, organKey, metricKey) {
  if (organKey === "__OVERALL__") {
    return metricKey === "dice" ? row.dice_med : metricKey === "centroid" ? row.centroid_med : row.hd95_med;
  }
  const o = row.organs[organKey];
  if (!o) return null;
  return metricKey === "dice" ? o.dice : metricKey === "centroid" ? o.centroid : o.hd95;
}

export default function OrganHeatmapDashboard() {
  const [metric, setMetric] = useState("dice");
  const [hideMissing, setHideMissing] = useState(false);

  const m = METRICS[metric];

  const groupedRows = useMemo(() => {
    const out = {};
    for (const g of GROUP_ORDER) {
      let rows = DATA.conditions.filter((c) => c.group === g);
      if (hideMissing) rows = rows.filter((r) => r.status !== "missing");
      out[g] = rows;
    }
    return out;
  }, [hideMissing]);

  return (
    <div className="w-full bg-slate-50 text-slate-900 font-sans">
      <div className="mx-auto max-w-6xl px-4 py-6">
        {/* Header */}
        <div className="mb-4">
          <h1 className="text-lg font-bold tracking-tight text-slate-900">
            Registration Pipeline &mdash; Per-Organ Heatmap
          </h1>
          <p className="mt-1.5 text-[12.5px] leading-relaxed text-slate-500 max-w-3xl">
            Median per-organ metric across each condition&rsquo;s reference set (matched N={DATA.matched_set_size} where available, otherwise all available studies).
            Color scale runs worst (red) &rarr; best (green); empty cells mean that organ had no valid measurements for that condition.
          </p>
        </div>

        {/* Controls */}
        <div className="mb-3 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-200 bg-white p-2.5">
          <div className="flex items-center gap-1.5">
            {Object.entries(METRICS).map(([key, def]) => (
              <button
                key={key}
                onClick={() => setMetric(key)}
                className={`rounded-lg px-3 py-1.5 text-[12px] font-medium transition-colors border ${
                  metric === key
                    ? "bg-indigo-600 text-white border-indigo-600"
                    : "bg-white text-slate-600 border-slate-200 hover:bg-slate-50"
                }`}
              >
                {def.label}
              </button>
            ))}
          </div>
          <label className="flex items-center gap-2 text-[12px] font-medium text-slate-600 cursor-pointer select-none">
            <input
              type="checkbox"
              checked={hideMissing}
              onChange={(e) => setHideMissing(e.target.checked)}
              className="h-3.5 w-3.5 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
            />
            Hide missing
          </label>
        </div>

        {/* Legend */}
        <div className="mb-3 flex items-center gap-2 text-[10.5px] text-slate-400">
          <span>worst</span>
          <div className="flex h-2.5 w-40 overflow-hidden rounded-full">
            {Array.from({ length: 24 }).map((_, i) => {
              const t = i / 23;
              const [r, g, b] = colorAt(t);
              return <div key={i} style={{ backgroundColor: `rgb(${r},${g},${b})`, width: "4.2%" }} />;
            })}
          </div>
          <span>best</span>
        </div>

        {/* Table */}
        <div className="overflow-x-auto rounded-xl border border-slate-200 bg-white shadow-sm">
          <table className="border-collapse text-[12px]" style={{ minWidth: "920px" }}>
            <thead>
              <tr className="border-b border-slate-200 bg-slate-50/90 text-left text-[10.5px] font-semibold uppercase tracking-wide text-slate-500">
                <th className="sticky left-0 z-20 bg-slate-50/95 px-3 py-2.5 backdrop-blur-sm" style={{ minWidth: "230px" }}>
                  Condition
                </th>
                {DATA.organs.map((o) => (
                  <th key={o} className="px-2 py-2.5 text-center" style={{ minWidth: "62px" }}>
                    {ORGAN_LABELS[o]}
                  </th>
                ))}
                <th className="px-2 py-2.5 text-center border-l border-slate-300 bg-slate-100/80" style={{ minWidth: "70px" }}>
                  OVERALL
                </th>
              </tr>
            </thead>
            <tbody>
              {GROUP_ORDER.map((g) => {
                const rows = groupedRows[g] || [];
                if (rows.length === 0) return null;
                const style = GROUP_STYLE[g];
                return (
                  <React.Fragment key={g}>
                    <tr className={`${style.head} border-b border-slate-200`}>
                      <td
                        colSpan={ORGAN_COLS.length + 1}
                        className={`sticky left-0 z-10 border-l-4 ${style.border} ${style.head} px-3 py-1.5 text-[10.5px] font-bold uppercase tracking-wide text-slate-600`}
                      >
                        <span className={`mr-2 inline-block h-1.5 w-1.5 rounded-full ${style.dot}`} />
                        {g}
                      </td>
                    </tr>
                    {rows.map((r) => (
                      <tr key={r.label} className="border-b border-slate-100 last:border-0 hover:bg-slate-50/60">
                        <td
                          className={`sticky left-0 z-10 border-l-4 ${style.border} bg-white px-3 py-1.5 align-middle ${
                            r.status === "missing" ? "opacity-50" : ""
                          }`}
                          style={{ minWidth: "230px" }}
                        >
                          <div className="flex items-center gap-1.5">
                            <span className="font-medium text-slate-800 truncate">{r.label}</span>
                            {r.flags && r.flags.includes("identical_pass2") && (
                              <span title="Identical to A4 \u2014 Pass 2 / B-spline not yet validated" className="text-amber-500 cursor-help">
                                \u26a0
                              </span>
                            )}
                          </div>
                          {r.status === "missing" && (
                            <span className="mt-0.5 inline-flex items-center gap-1 rounded-full border border-slate-300 bg-slate-100 px-1.5 py-0 text-[9.5px] font-semibold text-slate-500">
                              <XCircle className="h-2.5 w-2.5" /> MISSING
                            </span>
                          )}
                          {r.status === "partial" && (
                            <span className="mt-0.5 inline-flex items-center gap-1 rounded-full border border-amber-200 bg-amber-50 px-1.5 py-0 text-[9.5px] font-semibold text-amber-700">
                              <AlertTriangle className="h-2.5 w-2.5" /> PARTIAL &middot; N={r.n}
                            </span>
                          )}
                        </td>
                        {DATA.organs.map((o) => {
                          const v = organValue(r, o, metric);
                          const st = cellStyle(v, metric);
                          return (
                            <td key={o} className="px-1.5 py-1.5 text-center font-mono tabular-nums" style={st}>
                              {v === null ? "\u2014" : m.fmt(v)}
                            </td>
                          );
                        })}
                        {(() => {
                          const v = organValue(r, "__OVERALL__", metric);
                          const st = cellStyle(v, metric);
                          return (
                            <td className="px-1.5 py-1.5 text-center font-mono tabular-nums font-semibold border-l border-slate-300" style={st}>
                              {v === null ? "\u2014" : m.fmt(v)}
                            </td>
                          );
                        })()}
                      </tr>
                    ))}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>

        {/* Footnotes */}
        <div className="mt-4 flex items-start gap-2 rounded-xl border border-slate-200 bg-white p-3 text-[11.5px] leading-relaxed text-slate-500">
          <Info className="mt-0.5 h-3.5 w-3.5 flex-shrink-0 text-slate-400" />
          <div className="space-y-1">
            <p>
              Color domain: Dice 0&ndash;1 (higher = greener); Centroid 0&ndash;8&nbsp;mm and HD95 0&ndash;10&nbsp;mm (lower = greener), clamped beyond range.
            </p>
            <p>
              <span className="font-semibold text-slate-600">\u26a0 A5 / A6 / A5b / A6b:</span> identical to A4 / A4b on every organ in this CSV (Pass 2 rejected, B-spline not yet valid).
            </p>
            <p>
              Exact duplicate rows (re-runs with <span className="font-mono">--fill-missing</span>, e.g. <span className="font-mono">B5_unigradicon_io__baseline</span>) were removed before computing medians.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
